/**
 * Beekee Home - Meteor Methods (API Version)
 * 
 * Replaces all cmd() calls with REST API calls to beekee-system-api
 * 
 * API Base URL: http://127.0.0.1:5000/api/v1
 */

import { HTTP } from 'meteor/http'

// API Configuration
const API_BASE_URL = process.env.BEEKEE_API_URL || 'http://127.0.0.1:5000/api/v1';
const API_TIMEOUT = 30000; // 30 seconds

/**
 * Helper function to call the API
 */
function callAPI(method, endpoint, data = null) {
    const url = `${API_BASE_URL}${endpoint}`;
    const options = {
        timeout: API_TIMEOUT,
        headers: {
            'Content-Type': 'application/json'
        }
    };

    if (data) {
        options.data = data;
    }

    try {
        let result;
        
        switch(method.toUpperCase()) {
            case 'GET':
                result = HTTP.get(url, options);
                break;
            case 'POST':
                result = HTTP.post(url, options);
                break;
            case 'PUT':
                result = HTTP.put(url, options);
                break;
            case 'DELETE':
                result = HTTP.del(url, options);
                break;
            default:
                throw new Meteor.Error('invalid-method', `Unsupported HTTP method: ${method}`);
        }

        if (result.statusCode >= 200 && result.statusCode < 300) {
            return result.data;
        } else {
            throw new Meteor.Error('api-error', `API returned status ${result.statusCode}`, result.data);
        }
    } catch (error) {
        console.error(`API call failed: ${method} ${endpoint}`, error);
        
        // If it's already a Meteor.Error, re-throw it
        if (error.error) {
            throw error;
        }
        
        // Otherwise, create a new Meteor.Error
        throw new Meteor.Error('api-connection-error', 
            `Failed to connect to API: ${error.message}`,
            { method, endpoint, originalError: error.toString() }
        );
    }
}

